import { Array as Arr, Console, Effect, FileSystem, Order, Path } from "effect"
import { Command, Flag } from "effect/cli"
import { globSync } from "glob"

import { CheckFailed, SetupError } from "../errors.ts"
import { publishablePackages } from "../publishable.ts"

/** A built declaration file: its path relative to `dist` and its contents. */
export type Declaration = { readonly file: string; readonly source: string }

/**
 * The API report of a package: every public declaration file (outside `internal` folders), sorted,
 * without its source map comment. The report is committed, so a public API change shows in review.
 */
export const renderApiReport = (name: string, declarations: ReadonlyArray<Declaration>) =>
  Arr.join(
    [
      `# API report for \`${name}\``,
      "",
      "Generated by `pnpm api-snapshot` from the built declarations. Review every change: it is the package's public API.",
      "",
      ...Arr.flatMap(
        Arr.sort(declarations, Order.mapInput(Order.String, (declaration: Declaration) => declaration.file)),
        ({ file, source }) => [
          `## ${file}`,
          "",
          "```ts",
          source.replace(/\n\/\/# sourceMappingURL=.*\n?$/, "\n").trimEnd(),
          "```",
          ""
        ]
      )
    ],
    "\n"
  )

const run = Effect.fn("apiSnapshot")(
  function*(check: boolean) {
    const fs = yield* FileSystem.FileSystem
    const path = yield* Path.Path
    const root = process.cwd()
    const stale: Array<string> = []

    for (const pkg of yield* publishablePackages(root)) {
      const dist = path.join(pkg.dir, "dist")
      const files = globSync("**/*.d.ts", { cwd: dist, ignore: "**/internal/**" })
      if (files.length === 0) {
        return yield* SetupError.make({ message: `${pkg.name}: no declarations; run \`pnpm build\`` })
      }
      const declarations = yield* Effect.forEach(
        files,
        (file) => Effect.map(fs.readFileString(path.join(dist, file)), (source) => ({ file, source }))
      )
      const report = renderApiReport(pkg.name, declarations)
      const target = path.join(pkg.dir, "etc", `${path.basename(pkg.dir)}.api.md`)

      if (check) {
        const current = (yield* fs.exists(target)) ? yield* fs.readFileString(target) : undefined
        if (current !== report) stale.push(path.relative(root, target))
        continue
      }
      yield* fs.makeDirectory(path.dirname(target), { recursive: true })
      yield* fs.writeFileString(target, report)
      yield* Console.log(`api-snapshot: wrote ${path.relative(root, target)}`)
    }

    if (stale.length > 0) {
      return yield* CheckFailed.make({
        check: "api-snapshot",
        problems: [...stale, "the public API changed; run `pnpm api-snapshot` and review the diff"]
      })
    }
    if (check) yield* Console.log("api-snapshot: up to date")
  },
  Effect.catchTags({
    PlatformError: (cause) => SetupError.make({ message: String(cause) }),
    SchemaError: (cause) => SetupError.make({ message: String(cause) })
  })
)

export const apiSnapshot = Command.make("api-snapshot", {
  check: Flag.Boolean("check").pipe(
    Flag.withDefault(false),
    Flag.withDescription("Fail when a committed report differs instead of writing it")
  )
}, ({ check }) => run(check)).pipe(
  Command.withDescription("Write each package's API report (`etc/<name>.api.md`) from its built declarations")
)
